import {initializeApp} from "firebase/app";
import {getFirestore,connectFirestoreEmulator,query,collection,where,getDocs} from "firebase/firestore";
const app=initializeApp({projectId:"demo-reading-club"});
const db=getFirestore(app);connectFirestoreEmulator(db,"127.0.0.1",8080);
const request=query(collection(db,"books"),where("pages",">=",50));
const result=await getDocs(request);
result.forEach(item=>console.log(item.id,item.data().title));
